int gcd(int num1, int num2) {
    // Validate input: only non‑negative integers are allowed.
    // Zero is a valid argument because gcd(0, n) = n.
    if (num1 < 0 || num2 < 0) {
        throw std::domain_error("Euclidean algorithm domain is for non‑negative ints");
    }

    // Classic Euclidean algorithm using remainder (modulo).
    // This runs in O(log min(num1, num2)) time and does not create overlapping sub‑problems,
    // so no memoisation is required.
    while (num2 != 0) {
        int r = num1 % num2;
        num1 = num2;
        num2 = r;
    }
    return num1; // When num2 == 0, num1 holds the GCD (including the case gcd(0,0) -> 0).
}
